def solve(graph, start, end):
    if start == end:
        return 0
    visited = set()
    queue = [start]
    steps = 0
    while queue:
        new_queue = []
        for node in queue:
            if node == end:
                return steps
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    new_queue.append(neighbor)
        queue = new_queue
        steps += 1
    return -1
```

